fn ones_like<T>(a: &Vec<T>) -> Vec<i32> {
    let n = a.len();
    let mut result = Vec::with_capacity(n);
    let mut i = 0;

    // Loop from 0 up to n, pushing 1 each iteration.
    // Invariant: 0 ≤ i ≤ n, result.len() == i, and every element in result is 1.
    while i < n {
        result.push(1);
        i += 1;
    }

    result
}

